1	import { createReadStream, promises as fs } from "node:fs";
2	import path from "node:path";
3	import { createHash } from "node:crypto";
4	import { notFound } from "../errors.js";
5	import { resolvePaperclipInstanceRoot } from "../home-paths.js";
6	
7	export type RunLogStoreType = "local_file";
8	
9	export interface RunLogHandle {
10	  store: RunLogStoreType;
11	  logRef: string;
12	}
13	
14	export interface RunLogReadOptions {
15	  offset?: number;
16	  limitBytes?: number;
17	}
18	
19	export interface RunLogReadResult {
20	  content: string;
21	  nextOffset?: number;
22	}
23	
24	export interface RunLogFinalizeSummary {
25	  bytes: number;
26	  sha256?: string;
27	  compressed: boolean;
28	}
29	
30	export interface RunLogStore {
31	  begin(input: { companyId: string; agentId: string; runId: string }): Promise<RunLogHandle>;
32	  append(
33	    handle: RunLogHandle,
34	    event: { stream: "stdout" | "stderr" | "system"; chunk: string; ts: string },
35	  ): Promise<number>;
36	  finalize(handle: RunLogHandle): Promise<RunLogFinalizeSummary>;
37	  read(handle: RunLogHandle, opts?: RunLogReadOptions): Promise<RunLogReadResult>;
38	}
39	
40	function safeSegments(...segments: string[]) {
41	  return segments.map((segment) => segment.replace(/[^a-zA-Z0-9._-]/g, "_"));
42	}
43	
44	function resolveWithin(basePath: string, relativePath: string) {
45	  const resolved = path.resolve(basePath, relativePath);
46	  const base = path.resolve(basePath) + path.sep;
47	  if (!resolved.startsWith(base) && resolved !== path.resolve(basePath)) {
48	    throw new Error("Invalid log path");
49	  }
50	  return resolved;
51	}
52	
53	function createLocalFileRunLogStore(basePath: string): RunLogStore {
54	  async function ensureDir(relativeDir: string) {
55	    const dir = resolveWithin(basePath, relativeDir);
56	    await fs.mkdir(dir, { recursive: true });
57	  }
58	
59	  async function readFileRange(filePath: string, offset: number, limitBytes: number): Promise<RunLogReadResult> {
60	    const stat = await fs.stat(filePath).catch(() => null);
61	    if (!stat) throw notFound("Run log not found");
62	
63	    const start = Math.max(0, Math.min(offset, stat.size));
64	    const end = Math.max(start, Math.min(start + limitBytes - 1, stat.size - 1));
65	
66	    if (start > end) {
67	      return { content: "", nextOffset: start };
68	    }
69	
70	    const chunks: Buffer[] = [];
71	    await new Promise<void>((resolve, reject) => {
72	      const stream = createReadStream(filePath, { start, end });
73	      stream.on("data", (chunk) => {
74	        chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
75	      });
76	      stream.on("error", reject);
77	      stream.on("end", () => resolve());
78	    });
79	
80	    const content = Buffer.concat(chunks).toString("utf8");
81	    const nextOffset = end + 1 < stat.size ? end + 1 : undefined;
82	    return { content, nextOffset };
83	  }
84	
85	  async function sha256File(filePath: string): Promise<string> {
86	    return new Promise<string>((resolve, reject) => {
87	      const hash = createHash("sha256");
88	      const stream = createReadStream(filePath);
89	      stream.on("data", (chunk) => hash.update(chunk));
90	      stream.on("error", reject);
91	      stream.on("end", () => resolve(hash.digest("hex")));
92	    });
93	  }
94	
95	  return {
96	    async begin(input) {
97	      const [companyId, agentId] = safeSegments(input.companyId, input.agentId);
98	      const runId = safeSegments(input.runId)[0]!;
99	      const relDir = path.join(companyId, agentId);
100	      const relPath = path.join(relDir, `${runId}.ndjson`);
101	      await ensureDir(relDir);
102	
103	      const absPath = resolveWithin(basePath, relPath);
104	      await fs.writeFile(absPath, "", "utf8");
105	
106	      return { store: "local_file", logRef: relPath };
107	    },
108	
109	    async append(handle, event) {
110	      if (handle.store !== "local_file") return 0;
111	      const absPath = resolveWithin(basePath, handle.logRef);
112	      const line = JSON.stringify({
113	        ts: event.ts,
114	        stream: event.stream,
115	        chunk: event.chunk,
116	      });
117	      const persisted = `${line}\n`;
118	      await fs.appendFile(absPath, persisted, "utf8");
119	      return Buffer.byteLength(persisted, "utf8");
120	    },
121	
122	    async finalize(handle) {
123	      if (handle.store !== "local_file") {
124	        return { bytes: 0, compressed: false };
125	      }
126	      const absPath = resolveWithin(basePath, handle.logRef);
127	      const stat = await fs.stat(absPath).catch(() => null);
128	      if (!stat) throw notFound("Run log not found");
129	
130	      const hash = await sha256File(absPath);
131	      return {
132	        bytes: stat.size,
133	        sha256: hash,
134	        compressed: false,
135	      };
136	    },
137	
138	    async read(handle, opts) {
139	      if (handle.store !== "local_file") {
140	        throw notFound("Run log not found");
141	      }
142	      const absPath = resolveWithin(basePath, handle.logRef);
143	      const offset = opts?.offset ?? 0;
144	      const limitBytes = opts?.limitBytes ?? 256_000;
145	      return readFileRange(absPath, offset, limitBytes);
146	    },
147	  };
148	}
149	
150	let cachedStore: RunLogStore | null = null;
151	
152	export function getRunLogStore() {
153	  if (cachedStore) return cachedStore;
154	  const basePath = process.env.RUN_LOG_BASE_PATH ?? path.resolve(resolvePaperclipInstanceRoot(), "data", "run-logs");
155	  cachedStore = createLocalFileRunLogStore(basePath);
156	  return cachedStore;
157	}
